#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
#include <string.h>
static void note(const char*s){DWORD n;HANDLE f=CreateFileA("Z:\\tmp\\dextop-windows-display-probe.txt",FILE_APPEND_DATA,FILE_SHARE_READ|FILE_SHARE_WRITE,0,OPEN_ALWAYS,0,0);if(f!=INVALID_HANDLE_VALUE){WriteFile(f,s,(DWORD)strlen(s),&n,0);CloseHandle(f);}puts(s);fflush(stdout);}
int main(int argc,char **argv){char text[256];DEVMODEW mode={0};mode.dmSize=sizeof(mode);BOOL ok=EnumDisplaySettingsW(NULL,ENUM_CURRENT_SETTINGS,&mode);snprintf(text,sizeof(text),"DISPLAY_CURRENT ok=%d size=%ux%u bits=%u hz=%u fields=%08x\n",ok,(unsigned)mode.dmPelsWidth,(unsigned)mode.dmPelsHeight,(unsigned)mode.dmBitsPerPel,(unsigned)mode.dmDisplayFrequency,(unsigned)mode.dmFields);note(text);
 if(argc==2&&!strcmp(argv[1],"--set-current-60")){mode.dmFields=DM_PELSWIDTH|DM_PELSHEIGHT|DM_BITSPERPEL|DM_DISPLAYFREQUENCY;mode.dmDisplayFrequency=60;LONG change=ChangeDisplaySettingsExW(NULL,&mode,NULL,CDS_RESET,NULL);snprintf(text,sizeof(text),"DISPLAY_SET_REFRESH result=%ld\n",change);note(text);memset(&mode,0,sizeof(mode));mode.dmSize=sizeof(mode);ok=EnumDisplaySettingsW(NULL,ENUM_CURRENT_SETTINGS,&mode);snprintf(text,sizeof(text),"DISPLAY_AFTER_SET ok=%d hz=%u\n",ok,(unsigned)mode.dmDisplayFrequency);note(text);}for(unsigned i=0;i<4;i++){memset(&mode,0,sizeof(mode));mode.dmSize=sizeof(mode);ok=EnumDisplaySettingsW(NULL,i,&mode);snprintf(text,sizeof(text),"DISPLAY_MODE index=%u ok=%d size=%ux%u hz=%u\n",i,ok,(unsigned)mode.dmPelsWidth,(unsigned)mode.dmPelsHeight,(unsigned)mode.dmDisplayFrequency);note(text);if(!ok)break;}
 MONITORINFO info={.cbSize=sizeof(info)};HMONITOR monitor=MonitorFromPoint((POINT){0,0},MONITOR_DEFAULTTOPRIMARY);ok=GetMonitorInfoW(monitor,&info);snprintf(text,sizeof(text),"DISPLAY_MONITOR ok=%d rect=%ld,%ld,%ld,%ld\n",ok,info.rcMonitor.left,info.rcMonitor.top,info.rcMonitor.right,info.rcMonitor.bottom);note(text);return 0;}